async function writeClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    // Older Safari and insecure origins: a hidden textarea still works.
    const area = document.createElement('textarea')
    area.value = text
    area.setAttribute('readonly', '')
    area.style.position = 'fixed'
    area.style.opacity = '0'
    document.body.append(area)
    area.select()
    const ok = document.execCommand('copy')
    area.remove()
    return ok
  }
}

/**
 * The code as text anyone can select, plus a copy button whose icon morphs to
 * a check. The swap is masked with a short blur so it reads as one object
 * changing, not two crossfading; reduced motion keeps only the fade.
 */
export function PromoCode({
  code,
  onCopy,
  reveal = false,
  onReveal,
  className,
}: {
  code: string
  onCopy?: () => void
  /** Start hidden behind a "Reveal code" button. */
  reveal?: boolean
  onReveal?: () => void
  className?: string
}) {
  const labels = usePromotionLabels()
  const reduce = useReducedMotion()
  const [copied, setCopied] = React.useState(false)
  const [revealed, setRevealed] = React.useState(!reveal)
  const revealRef = React.useRef<HTMLButtonElement>(null)
  React.useEffect(() => {
    if (!copied) return
    const timer = window.setTimeout(() => setCopied(false), 1600)
    return () => window.clearTimeout(timer)
  }, [copied])

  const hidden = reduce
    ? { opacity: 0 }
    : { opacity: 0, scale: 0.8, filter: 'blur(2px)' }

  if (!revealed) {
    return (
      <span className={cn('inline-flex items-center gap-2 text-sm', className)}>
        <span
          aria-hidden
          className="rounded-lg border border-dashed border-current/35 px-2 py-0.5 font-mono font-medium tracking-wider opacity-60 blur-[5px] select-none"
        >
          {code.replace(/./g, '•')}
        </span>
        <Button
          ref={revealRef}
          type="button"
          size="sm"
          variant="outline"
          className="border-current/25 bg-transparent text-current hover:bg-current/10 hover:text-current"
          onClick={() => {
            setRevealed(true)
            onReveal?.()
          }}
        >
          {labels.reveal}
        </Button>
      </span>
    )
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-lg border border-dashed border-current/35 py-0.5 ps-2 pe-0.5 text-sm',
        className,
      )}
    >
      <span
        className={cn(
          'font-mono font-medium tracking-wider select-all',
          reveal &&
            'animate-in duration-300 ease-[cubic-bezier(0.23,1,0.32,1)] fade-in-0 motion-reduce:animate-none',
        )}
      >
        {code}
      </span>
      <button
        type="button"
        aria-label={labels.copyCode(code)}
        onClick={async () => {
          if (await writeClipboard(code)) {
            setCopied(true)
            onCopy?.()
          }
        }}
        className="relative grid size-7 place-items-center rounded-md transition-[background-color,transform] duration-150 ease-out outline-none hover:bg-current/10 focus-visible:ring-3 focus-visible:ring-current/30 active:scale-[0.96]"
      >
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={copied ? 'done' : 'copy'}
            initial={hidden}
            animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
            exit={hidden}
            transition={{ duration: 0.16, ease: PROMO_EASE_OUT }}
            className="grid place-items-center"
          >
            {copied ? (
              <IconCheck aria-hidden className="size-4" />
            ) : (
              <IconCopy aria-hidden className="size-4" />
            )}
          </motion.span>
        </AnimatePresence>
      </button>
      <span role="status" className="sr-only">
        {copied ? labels.copied : ''}
      </span>
    </span>
  )
}

function IconAction({
  onAction,
  label,
