import type { DismissScope } from './promotion'

/**
 * Where visitor state lives: dismissals, when a surface was last shown, a
 * minimised toast. Values are epoch ms; `null` means never written.
 *
 * Every promotion names a scope (see `dismissScope`), and the provider asks
 * the store for that scope. Compose one store per scope with `composeStores`.
 */
export type DismissalStore = {
  get: (key: string, scope: DismissScope) => number | null
  set: (key: string, at: number, scope: DismissScope) => void
  /** Optional: call `onChange` when another tab or device writes. */
  subscribe?: (onChange: () => void) => () => void
}

function safeStorage(kind: 'local' | 'session'): Storage | null {
  try {
    return kind === 'local' ? window.localStorage : window.sessionStorage
  } catch {
    return null
  }
}

function readNumber(raw: string | null | undefined): number | null {
  const value = raw ? Number(raw) : Number.NaN
  return Number.isFinite(value) ? value : null
}

/**
 * sessionStorage for `tab`, localStorage for everything else. Storage can
 * throw in private windows; reads then return null and writes are dropped,
 * while the provider still honours the dismissal for the current page.
 */
export const browserDismissalStore: DismissalStore = {
  get(key, scope) {
    try {
      return readNumber(
        safeStorage(scope === 'tab' ? 'session' : 'local')?.getItem(key),
      )
    } catch {
      return null
    }
  },
  set(key, at, scope) {
    try {
      const storage = safeStorage(scope === 'tab' ? 'session' : 'local')
      if (Number.isFinite(at)) storage?.setItem(key, String(at))
      else storage?.removeItem(key)
    } catch {
      // Private window or quota: the provider keeps it in memory.
    }
  },
  subscribe(onChange) {
    const onStorage = (event: StorageEvent) => {
      if (event.key === null || event.key.startsWith('promo:')) onChange()
    }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  },
}

/** Cookie names allow a narrower alphabet than storage keys. */
const cookieName = (key: string) => key.replace(/[^\w-]/g, '_')

/**
 * Parses a `Cookie` header (or `document.cookie`) into promotion values, so
 * a server component can pass them down and render an inline bar with no
 * layout shift: `readPromotionCookies((await cookies()).toString())`.
 */
export function readPromotionCookies(header: string): Map<string, number> {
  const values = new Map<string, number>()
  for (const part of header.split(';')) {
    const [rawName, ...rest] = part.trim().split('=')
    if (!rawName?.startsWith('promo_')) continue
    let decoded: string
    try {
      decoded = decodeURIComponent(rest.join('='))
    } catch {
      // One malformed cookie must not break rendering; skip just that one.
      continue
    }
    const value = readNumber(decoded)
    if (value !== null) values.set(rawName, value)
  }
  return values
}

/**
 * First-party cookies, readable by the server. Only epoch numbers are
 * stored, never anything about the visitor. Whether this needs consent
 * depends on your region and use; a dismissal the visitor asked for is
 * usually treated as strictly necessary.
 */
export function cookieDismissalStore({
  maxAgeDays = 365,
  path = '/',
  initial,
}: {
  maxAgeDays?: number
  path?: string
  /** Values read on the server with `readPromotionCookies`, for the first render. */
  initial?: ReadonlyMap<string, number>
} = {}): DismissalStore {
  return {
    get(key) {
      const name = cookieName(key)
      if (typeof document === 'undefined') return initial?.get(name) ?? null
      return readPromotionCookies(document.cookie).get(name) ?? null
    },
    set(key, at) {
      if (typeof document === 'undefined') return
      const name = cookieName(key)
      const age = Number.isFinite(at) ? maxAgeDays * 86_400 : 0
      document.cookie = `${name}=${Number.isFinite(at) ? at : ''}; Max-Age=${age}; Path=${path}; SameSite=Lax${location.protocol === 'https:' ? '; Secure' : ''}`
    },
  }
}

/** In memory only. For previews, tests and demos. */
export function memoryDismissalStore(): DismissalStore & { clear: () => void } {
  const map = new Map<string, number>()
  const id = (key: string, scope: DismissScope) => `${scope}|${key}`
  return {
    get: (key, scope) => map.get(id(key, scope)) ?? null,
    set: (key, at, scope) => {
      if (Number.isFinite(at)) map.set(id(key, scope), at)
      else map.delete(id(key, scope))
    },
    clear: () => map.clear(),
  }
}

/**
 * One store per scope. Scopes without a store fall back to `browser` (and
 * `browser` to the default), so a site can add `account` later without
 * touching its promotions.
 *
 * ```ts
 * composeStores({ cookie: cookieDismissalStore(), account: myApiStore })
 * ```
 */
export function composeStores(
  stores: Partial<Record<DismissScope, DismissalStore>>,
): DismissalStore {
  const browser = stores.browser ?? browserDismissalStore
  const pick = (scope: DismissScope) =>
    stores[scope] ?? (scope === 'tab' ? browserDismissalStore : browser)
  const unique = [...new Set(Object.values(stores))]
  return {
    get: (key, scope) => pick(scope).get(key, scope),
    set: (key, at, scope) => pick(scope).set(key, at, scope),
    subscribe: (onChange) => {
      const offs = [browserDismissalStore, ...unique].map((store) =>
        store.subscribe?.(onChange),
      )
      return () => offs.forEach((off) => off?.())
    },
  }
}

import type { Promotion } from './promotion'
import type { PromotionEvent } from './promotion-provider'

export type PromotionPluginContext = {
  pathname: string
  now: () => number
  /**
   * Counts as engagement for this page, as if the delay and scroll depth had
   * been met. The provider's other rules still apply: frequency, the daily
   * budget, dismissals, and never over a busy visitor.
   */
  engage: (placement: 'toast' | 'dialog') => void
}

/**
 * Add-ons extend the provider without growing its props. Each hook is
 * optional; keep the `plugins` array stable (define it outside render).
 */
export type PromotionPlugin = {
  name: string
  /** Veto a candidate, e.g. hide incentives from people who just bought. */
  allow?: (
    promotion: Promotion,
    context: { pathname: string; now: number },
  ) => boolean
  /** Extra triggers. Runs per page; return a cleanup. */
  setup?: (context: PromotionPluginContext) => (() => void) | void
  /** Sees every event, e.g. to forward to an analytics vendor. */
  onEvent?: (event: PromotionEvent) => void
}

/**
 * Opens a toast or dialog when a mouse leaves through the top of the window,
 * which usually means heading for the tabs or the close button.
 *
 * Desktop only by design: the phone equivalents (sudden scroll-up, trapping
 * the back button) feel hostile, so there are none. It waits `minDwellMs` on
 * the page first, and the provider's frequency rules keep it to once a day.
 */
export function exitIntent({
  placement = 'dialog',
  minDwellMs = 4000,
}: {
  placement?: 'toast' | 'dialog'
  minDwellMs?: number
} = {}): PromotionPlugin {
  return {
    name: 'exit-intent',
    setup({ engage, pathname }) {
      if (!window.matchMedia?.('(hover: hover) and (pointer: fine)').matches)
        return
      const arrived = performance.now()
      const onLeave = (event: MouseEvent) => {
        if (event.relatedTarget !== null || event.clientY > 0) return
        if (performance.now() - arrived < minDwellMs) return
        engage(placement)
      }
      document.addEventListener('mouseout', onLeave)
      void pathname
      return () => document.removeEventListener('mouseout', onLeave)
    },
  }
}

/**
 * Opens after the visitor has been idle for `ms`: no pointer, key or scroll.
 * A pause often means "thinking it over", a fair moment for a quiet toast.
 */
export function idle({
  placement = 'toast',
  ms = 20_000,
}: { placement?: 'toast' | 'dialog'; ms?: number } = {}): PromotionPlugin {
  return {
    name: 'idle',
    setup({ engage }) {
      let timer = window.setTimeout(() => engage(placement), ms)
      const reset = () => {
        window.clearTimeout(timer)
        timer = window.setTimeout(() => engage(placement), ms)
      }
      const events = ['pointermove', 'keydown', 'scroll', 'touchstart'] as const
      for (const type of events)
        window.addEventListener(type, reset, { passive: true })
      return () => {
        window.clearTimeout(timer)
        for (const type of events) window.removeEventListener(type, reset)
      }
    },
  }
}

/**
 * Hides promotions whose `campaign` is in `exclude()`, e.g. the host's list
 * of campaigns this visitor already converted on. Runs on every selection.
 */
export function excludeCampaigns(
  exclude: () => readonly string[],
): PromotionPlugin {
  return {
    name: 'exclude-campaigns',
    allow: (promotion) =>
      !promotion.campaign || !exclude().includes(promotion.campaign),
  }
}

'use client'

import * as React from 'react'
import { IconChevronLeft, IconChevronRight } from '@tabler/icons-react'
import { useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'

import type { PromotionMedia } from './promotion'

/**
 * A native scroll-snap carousel: the browser does the swiping, momentum and
 * snapping, so it feels right on every device and costs no JavaScript per
 * frame. We only add what scroll-snap lacks: previous and next buttons (for
 * pointers, gated behind hover), dots, arrow keys, and which slide is showing.
 *
 * It never advances on its own: moving content steals attention and is hard
 * to read, so the visitor stays in control.
 */
export function PromoGallery({
  images,
  className,
  aspect = '16 / 9',
  label = 'Images',
  eager = false,
  onSlide,
}: {
  images: readonly PromotionMedia[]
  className?: string
  /** CSS aspect-ratio for every slide, so nothing shifts while loading. */
  aspect?: string
  /** Accessible name for the carousel region. */
  label?: string
  /** Load the first image eagerly (dialogs, sheets). */
  eager?: boolean
  onSlide?: (index: number) => void
}) {
  const reduce = useReducedMotion()
  const scroller = React.useRef<HTMLDivElement>(null)
  const slides = React.useRef<(HTMLDivElement | null)[]>([])
  const [active, setActive] = React.useState(0)
  const onSlideRef = React.useRef(onSlide)
  React.useLayoutEffect(() => {
    onSlideRef.current = onSlide
  })

  React.useEffect(() => {
    const root = scroller.current
    if (!root || typeof IntersectionObserver === 'undefined') return
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue
          const index = slides.current.indexOf(entry.target as HTMLDivElement)
          if (index >= 0) {
            setActive(index)
            onSlideRef.current?.(index)
          }
        }
      },
      { root, threshold: 0.6 },
    )
    for (const slide of slides.current) if (slide) observer.observe(slide)
    return () => observer.disconnect()
  }, [images])

  const go = (index: number) => {
    const target = slides.current[(index + images.length) % images.length]
    target?.scrollIntoView({
      behavior: reduce ? 'auto' : 'smooth',
      block: 'nearest',
      inline: 'start',
    })
  }

  if (images.length === 0) return null
  if (images.length === 1) {
    const image = images[0]!
    return (
      // oxlint-disable-next-line nextjs/no-img-element
      <img
        src={image.src}
        alt={image.alt}
        width={image.width}
        height={image.height}
        loading={eager ? 'eager' : 'lazy'}
        decoding="async"
        style={{ aspectRatio: aspect }}
        className={cn('w-full bg-current/5 object-cover', className)}
      />
    )
  }

  return (
    <div
      role="region"
      aria-roledescription="carousel"
      aria-label={label}
      className={cn(
        'group/gallery relative isolate overflow-hidden',
        className,
      )}
      onKeyDown={(event) => {
        if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
          event.preventDefault()
          const rtl = getComputedStyle(event.currentTarget).direction === 'rtl'
          const forward = (event.key === 'ArrowRight') !== rtl
          go(active + (forward ? 1 : -1))
        }
      }}
    >
      <div
        ref={scroller}
        tabIndex={0}
        className="focus-visible:ring-ring/50 flex snap-x snap-mandatory overflow-x-auto overscroll-x-contain outline-none [scrollbar-width:none] focus-visible:ring-3 focus-visible:ring-inset [&::-webkit-scrollbar]:hidden"
      >
        {images.map((image, index) => (
          <div
            key={`${image.src}-${index}`}
            ref={(node) => {
              slides.current[index] = node
            }}
            role="group"
            aria-roledescription="slide"
            aria-label={`${index + 1} / ${images.length}`}
            className="w-full shrink-0 snap-start snap-always"
          >
            {/* oxlint-disable-next-line nextjs/no-img-element */}
            <img
              src={image.src}
              alt={image.alt}
              width={image.width}
              height={image.height}
              loading={eager && index === 0 ? 'eager' : 'lazy'}
              decoding="async"
              draggable={false}
              style={{ aspectRatio: aspect }}
              className="w-full bg-current/5 object-cover select-none"
            />
          </div>
        ))}
      </div>

      <span
        aria-hidden
        className="absolute start-2 top-2 rounded-full bg-black/55 px-2 py-0.5 text-[0.6875rem] font-medium text-white tabular-nums backdrop-blur-sm"
      >
        {active + 1}/{images.length}
      </span>

      {(['prev', 'next'] as const).map((which) => (
        <button
          key={which}
          type="button"
          aria-label={which === 'prev' ? 'Previous image' : 'Next image'}
          onClick={() => go(active + (which === 'prev' ? -1 : 1))}
          className={cn(
            'absolute top-1/2 grid size-8 -translate-y-1/2 place-items-center rounded-full bg-white/85 text-black opacity-0 shadow-md ring-1 ring-black/5 backdrop-blur-sm transition-[opacity,transform] duration-150 ease-out outline-none focus-visible:opacity-100 focus-visible:ring-3 focus-visible:ring-ring/60 active:scale-[0.96] [@media(hover:hover)]:group-hover/gallery:opacity-100',
            which === 'prev' ? 'start-2' : 'end-2',
          )}
        >
          {which === 'prev' ? (
            <IconChevronLeft aria-hidden className="size-4 rtl:-scale-x-100" />
          ) : (
            <IconChevronRight aria-hidden className="size-4 rtl:-scale-x-100" />
          )}
        </button>
      ))}

      <div className="absolute inset-x-0 bottom-2 flex justify-center gap-1.5">
        {images.map((image, index) => (
          <button
            key={`dot-${image.src}-${index}`}
            type="button"
            aria-label={`Image ${index + 1} of ${images.length}`}
            aria-current={index === active ? 'true' : undefined}
            onClick={() => go(index)}
            className="grid size-4 place-items-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-white"
          >
            <span
              className={cn(
                'block h-1.5 rounded-full bg-white shadow-sm transition-[width,opacity] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none',
                index === active ? 'w-3.5 opacity-100' : 'w-1.5 opacity-60',
              )}
            />
          </button>
        ))}
      </div>
    </div>
  )
}
